# -*- coding: utf-8 -*-
S = "волна 146, повторная правка отложенных задач: все объяснения дистракторов пересчитаны"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)

E('G10_TB_3_8_4_d', 'объяснения дистракторов не давали своих значений; значения заменены на результаты реальных ошибок (проверено численно)',
  dnew={0: (r'$x \in (-\infty; 1) \cup \left(\dfrac{5}{4}; +\infty\right)$',
            r'Ученик решил только условие $0<\dfrac{x-1}{5x-6}<1$ (откуда $x<1$ или $x>\dfrac{5}{4}$) и не наложил требование $0<\sqrt{6}-2x<1$.'),
        1: (r'$x \in \left(\dfrac{6}{5}; \dfrac{\sqrt{6}}{2}\right)$',
            r'Ученик перепутал случаи: для основания больше $1$ (то есть $\dfrac{6}{5}<x<\dfrac{5}{4}$) взял условие $0<\sqrt{6}-2x<1$, то есть $\dfrac{\sqrt{6}-1}{2}<x<\dfrac{\sqrt{6}}{2}$; пересечение даёт $\left(\dfrac{6}{5}; \dfrac{\sqrt{6}}{2}\right)$.'),
        2: (r'$x \in \left(-\infty; \dfrac{\sqrt{6} - 1}{2}\right)$',
            r'Ученик при основании между $0$ и $1$ не поменял знак: потребовал $\sqrt{6}-2x>1$, то есть $x<\dfrac{\sqrt{6}-1}{2}$; вместе с $x<1$ получилось $\left(-\infty; \dfrac{\sqrt{6}-1}{2}\right)$.')})

E('G5_TB_13_548.1', 'объяснения дистракторов не давали своих значений (забытый заём даёт 576739, а не 576719; 665313 не воспроизводился) — пересчитаны',
  dnew={0: (r'$576739$',
            r'Ученик в столбик вычел $675332-98603$: занял десяток для разряда единиц ($12-3=9$), но не уменьшил разряд десятков на $1$, получив $3-0=3$ вместо $2$; итог на $10$ больше.'),
        2: (r'$773935$',
            r'Ученик верно получил $675019+313=675332$, но вместо вычитания $98603$ прибавил его: $675332+98603=773935$.')},
  dwhy={1: r'Ученик ошибся при делении в столбик $88892:284$ и получил $625$ вместо $313$. Тогда $675019+625-98603=577041$.'})

E('G6_TB_11–12_108.1', 'объяснение дистрактора 15 не описывало ошибку; объяснения переписаны так, чтобы описывать ошибку',
  dwhy={0: r'Ученик посчитал множители с повторением: $12=2\cdot2\cdot3$ — три множителя, но различных простых делителей только два ($2$ и $3$).',
        1: r'Ученик посчитал множители с повторением: $8=2\cdot2\cdot2$ — три множителя, но простой делитель один ($2$).',
        2: r'Ученик причислил к простым делителям число $1$: $1$, $3$, $5$ — «три», но $1$ не простое, и у $15=3\cdot5$ простых делителей только два.'})

E('G7_ALG_1_5', 'объяснения дистракторов не давали своих значений (в «1, 2, 3, 5» говорилось только про 5; про 6 не было ошибки) — значения и объяснения согласованы',
  dnew={0: (r'$1, 2, 4$',
            r'Ученик сравнил части равенства 4) только по целым частям: $1\dfrac{2}{3}+4\dfrac{1}{5}=5\dfrac{13}{15}$ и $41{,}5\cdot\dfrac{2}{15}=\dfrac{83}{15}=5\dfrac{8}{15}$ — оба «пять с лишним»; дробные части $\dfrac{13}{15}$ и $\dfrac{8}{15}$ не сравнил и счёл равенство верным.'),
        1: (r'$1, 2, 5$',
            r'Ученик принял $\dfrac{21}{34}$ за $\dfrac{14}{17}$ (а на деле $\dfrac{14}{17}=\dfrac{28}{34}$), счёл обе части равенства 5) одинаковыми, хотя $1-\dfrac{14}{17}=\dfrac{6}{34}$, а $1-\dfrac{21}{34}=\dfrac{13}{34}$.'),
        2: (r'$2$',
            r'Ученик сложил дроби в равенстве 1) «по числителям и знаменателям»: $\dfrac{3+3}{10+4}=\dfrac{3}{7}\ne\dfrac{21}{20}$, счёл 1) неверным, поэтому осталось только 2).'),
        3: (r'$1, 2, 3$',
            r'Ученик в равенстве 3) сравнил только дробные части: в обеих частях получается $\dfrac{67}{70}$, а целые части ($17$ и $16$) не сравнил.')})

E('G7_ALG_23_8.1', 'значения дистракторов 1 и 2 не соответствовали своим объяснениям (a вместо a^2 в числителе; 3 вместо 1) — значения пересчитаны',
  dnew={1: (r'$\dfrac{3ab^{2}}{15a^{3}b^{2}}$, $\dfrac{a^{2}(a^{2}+b^{2})}{15a^{3}b^{2}}$, $\dfrac{5ab(b-1)}{15a^{3}b^{2}}$',
            r'Ученик взял в общем знаменателе $a^{3}$ вместо $a^{2}$ и честно подобрал множители к $15a^{3}b^{2}$: $3ab^{2}$, $a^{2}$ и $5ab$.'),
        2: (r'$\dfrac{1}{15a^{2}b^{2}}$, $\dfrac{a^{2}+b^{2}}{15a^{2}b^{2}}$, $\dfrac{b-1}{15a^{2}b^{2}}$',
            r'Ученик верно нашёл общий знаменатель $15a^{2}b^{2}$, но числители оставил прежними, не умножив на дополнительные множители $3b^{2}$, $a$ и $5b$.')})

E('G7_TB_32_836.2', 'выкладки дистракторов не давали заявленных результатов, в одном значении были лишние «$» — переписаны и обёрнуты в $…$',
  dnew={0: (r'$(x + y)^{2} - (x - y)^{2} = (x^{2} + 2xy + y^{2}) - (x^{2} - 2xy + y^{2}) = x^{2} + 2xy + y^{2} - x^{2} - 2xy + y^{2} = 2y^{2}$',
            r'Ученик при раскрытии скобок со знаком «минус» поменял знак только у первого слагаемого: $-x^{2}-2xy+y^{2}$, откуда $2y^{2}$.'),
        1: (r'$(x + y)^{2} - (x - y)^{2} = (x^{2} + y^{2}) - (x^{2} + y^{2}) = 0$',
            r'Ученик раскрыл оба квадрата без удвоенного произведения: $(x+y)^{2}=x^{2}+y^{2}$ и $(x-y)^{2}=x^{2}+y^{2}$, поэтому разность равна $0$.'),
        2: (r'$(x + y)^{2} - (x - y)^{2} = ((x + y) - (x - y))^{2} = (2y)^{2} = 4y^{2}$',
            r'Ученик заменил разность квадратов квадратом разности: $((x+y)-(x-y))^{2}=(2y)^{2}=4y^{2}$.')})

E('G9_TB_15_255', 'объяснения дистракторов 1 (неверное уравнение) пересчитано; значение «2 ч» теперь получено потерей корня',
  dnew={1: (r'$2$ ч',
            r'Ученик нашёл оба корня $x=12$ и $x=15$, но в ответ взял только время при скорости $15$ км/ч: $30:15=2$ ч, потеряв $30:12=2{,}5$ ч.')})

E('G9_TB_27_318_4', 'объяснения дистракторов не воспроизводили значения (cos 2α — общий текст; 0 — не вычислялось) — пересчитаны',
  dwhy={0: r'Ученик перешёл к $\dfrac{\cos\left(2\alpha-\frac{\pi}{2}\right)-\cos\left(2\alpha+\frac{\pi}{2}\right)}{2}$, но в формуле разности косинусов вместо $\sin\dfrac{P+Q}{2}$ записал $\cos\dfrac{P+Q}{2}$: $-\dfrac{2\cos2\alpha\sin\left(-\frac{\pi}{2}\right)}{2}=\cos2\alpha$.',
        1: r'Ученик применил $\cos^{2}A-\cos^{2}B=-\sin(A+B)\sin(A-B)$, но вместо $\sin(A-B)$ взял $\cos(A-B)$: $-\sin2\alpha\cdot\cos\left(-\dfrac{\pi}{2}\right)=-\sin2\alpha\cdot0=0$.',
        2: r'Ученик применил $\cos^{2}A-\cos^{2}B=\sin(B-A)\sin(B+A)$ при $A=\alpha-\dfrac{\pi}{4}$, $B=\alpha+\dfrac{\pi}{4}$, но перепутал порядок: взял $\sin(A-B)=\sin\left(-\dfrac{\pi}{2}\right)=-1$, и получил $-\sin2\alpha$.'})
